B.H8=s(["\uacf5\ud45c\uba85\ub839\uc758 \uc778\uc815"],t.s)
B.at3=new A.b("gen_clause_review_order_5","economic_law","\uc57d\uad00 \uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28","\uc2dc\uc815\uad8c\uace0\xb7\uc2dc\uc815\uba85\ub839","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc2dc\uc815\uba85\ub839\uacfc \ud568\uaed8 \uadf8 \uc0ac\uc2e4\uc758 \uacf5\ud45c\ub97c \uba85\ud560 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Ju,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \ubd88\uacf5\uc815\uc57d\uad00\uc870\ud56d \uc0ac\uc6a9 \uc0ac\uc2e4\uc744 \uc2dc\uc815\ud558\ub3c4\ub85d \uba85\ud558\uba74\uc11c, \uc720\uc0ac\ud55c \uc57d\uad00\uc73c\ub85c \uc778\ud55c \ud53c\ud574\uac00 \ub2e4\ub978 \uace0\uac1d\uc5d0\uac8c \ud655\uc0b0\ub418\ub294 \uac83\uc744 \ubc29\uc9c0\ud560 \ud544\uc694\uac00 \uc788\ub294 \uacbd\uc6b0 \uadf8 \uc704\ubc18 \uc0ac\uc2e4 \ub4f1\uc744 \uacf5\ud45c\ud558\ub3c4\ub85d \uba85\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \uc81c\ub3c4\uc758 \ucde8\uc9c0\uc5d0 \ubd80\ud569\ud55c\ub2e4.",B.Wf,B.H8,null)
B.a2a=s(["\ubc18\ubcf5 \uc704\ubc18\uc73c\ub85c\uc11c \uac00\uc911\ub41c \uc81c\uc7ac\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4","\ubc18\ubcf5 \uc0ac\uc6a9\uc740 \uc5b4\ub5a0\ud55c \ubb38\uc81c\ub3c4 \ub418\uc9c0 \uc54a\ub294\ub2e4","\ubc18\ubcf5 \uc0ac\uc6a9\uc740 \uc624\ud788\ub824 \uac10\uacbd\uc0ac\uc720\ub85c \uc791\uc6a9\ud55c\ub2e4","\ubc18\ubcf5 \uc0ac\uc6a9 \uc5ec\ubd80\ub294 \uc81c\uc7ac \uc218\uc704\uc640 \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\ubc18\ubcf5 \uc0ac\uc6a9\uc740 \ucd5c\ucd08 \uc704\ubc18\ubcf4\ub2e4 \ud56d\uc0c1 \uac00\ubccd\uac8c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.UM=s(["\ubc18\ubcf5 \uc704\ubc18\uc73c\ub85c\uc11c \uac00\uc911\ub41c \uc81c\uc7ac\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.abT=s(["\ubc18\ubcf5 \uc704\ubc18\uc758 \uac00\uc911\uc81c\uc7ac"],t.s)
B.av6=new A.b("gen_clause_review_order_6","economic_law","\uc57d\uad00 \uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28","\uc2dc\uc815\uad8c\uace0\xb7\uc2dc\uc815\uba85\ub839","\uc2dc\uc815\uba85\ub839\uc774 \ud655\uc815\ub41c \uc774\ud6c4 \uc0ac\uc5c5\uc790\uac00 \ub3d9\uc77c\ud55c \ubd88\uacf5\uc815\uc57d\uad00\uc870\ud56d\uc744 \ub2e4\uc2dc \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uc758 \ucde8\uae09\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a2a,0,"\uc2dc\uc815\uba85\ub839\uc774 \ud655\uc815\ub418\uc5b4 \uc704\ubc18 \uc870\ud56d\uc744 \uc0ad\uc81c\xb7\uc218\uc815\ud574\uc57c \ud568\uc5d0\ub3c4 \uc0ac\uc5c5\uc790\uac00 \ub3d9\uc77c\ud558\uac70\ub098 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc720\uc0ac\ud55c \ubd88\uacf5\uc815\uc57d\uad00\uc870\ud56d\uc744 \ub2e4\uc2dc \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uc5d0\ub294, \uc774\ub294 \ubc18\ubcf5 \uc704\ubc18\uc73c\ub85c\uc11c \ud1b5\uc0c1\uc758 \uc704\ubc18\ubcf4\ub2e4 \ub354 \ubb34\uac70\uc6b4 \uac00\uc911\ub41c \uc81c\uc7ac\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4.",B.UM,B.abT,null)
B.a6t=s([u.bv,"\uc2dc\uc815\uc870\uce58\uac00 \ub0b4\ub824\uc9c0\uba74 \uad00\ub828\ub41c \ubaa8\ub4e0 \uacc4\uc57d\uc774 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4","\uc2dc\uc815\uc870\uce58\ub294 \uac1c\ubcc4 \uacc4\uc57d\uc758 \ud6a8\ub825\uacfc \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uac83\uc774\ub2e4","\uc2dc\uc815\uc870\uce58\uac00 \uc788\uc73c\uba74 \ubbfc\uc0ac\uc18c\uc1a1\uc740 \uc804\ud600 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4","\uc2dc\uc815\uc870\uce58\ub294 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uc5d0 \uc5b4\ub5a0\ud55c \uc601\ud5a5\ub3c4 \ubbf8\uce60 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \uc808\ub300\uc801 \uc6d0\uce59\uc774\ub2e4"],t.s)
B.aba=s([u.bv],t.s)
B.a5o=s(["\uc2dc\uc815\uc870\uce58\uc640 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uc758 \uad00\uacc4"],t.s)
B.aqv=new A.b("gen_clause_review_effect_1","economic_law","\uc57d\uad00 \uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28","\uc2dc\uc815\uc870\uce58\uc758 \ud6a8\ub825\xb7\ubd88\ubcf5\uc808\ucc28","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc57d\uad00 \uc2dc\uc815\uc870\uce58\uac00 \uac1c\ubcc4 \uacc4\uc57d\uc758 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a6t,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc2dc\uc815\uc870\uce58\ub294 \ud589\uc815\uc801 \uc81c\uc7ac\uc758 \uc131\uaca9\uc744 \uac00\uc9c0\uba70, \uadf8 \uc790\uccb4\ub85c \uac1c\ubcc4 \uacc4\uc57d\uc758 \uc0ac\ubc95\uc0c1 \ud6a8\ub825(\ud574\ub2f9 \uc870\ud56d\uc758 \ubb34\ud6a8 \uc5ec\ubd80 \ub4f1)\uc744 \uc9c1\uc811 \ud655\uc815\ud558\ub294 \uac83\uc740 \uc544\ub2c8\uc5b4\uc11c, \uad6c\uccb4\uc801\uc778 \uacc4\uc57d\uc758 \ud6a8\ub825\uc740 \ubcc4\ub3c4\ub85c \ubbfc\uc0ac\uc18c\uc1a1\uc744 \ud1b5\ud574 \ub2e4\ud22c\uc5b4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc778 \ubc95\ub9ac\ub85c \uc774\ud574\ub41c\ub2e4.",B.aba,B.a5o,null)
B.a4J=s(["\uc774\uc758\uc2e0\uccad\uc774\ub098 \ud589\uc815\uc18c\uc1a1 \ub4f1 \uc77c\ubc18\uc801\uc778 \ubd88\ubcf5\uc808\ucc28\ub97c \ud1b5\ud574 \ub2e4\ud234 \uc218 \uc788\ub2e4","\uc2dc\uc815\uba85\ub839\uc5d0\ub294 \uc5b4\ub5a0\ud55c \ubd88\ubcf5\ub3c4 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ubd88\ubcf5\uc740 \uc624\uc9c1 \ud615\uc0ac\ubc95\uc6d0\uc744 \ud1b5\ud574\uc11c\ub9cc \uac00\ub2a5\ud558\ub2e4","\ubd88\ubcf5\ud558\uba74 \uc790\ub3d9\uc73c\ub85c \uc2dc\uc815\uba85\ub839\uc774 \ucde8\uc18c\ub41c\ub2e4","\uc2dc\uc815\uba85\ub839\uc740 \ubd88\ubcf5 \uc808\ucc28 \uc790\uccb4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \ud2b9\uc218\ud55c \ucc98\ubd84\uc774\ub2e4"],t.s)
B.aam=s(["\uc774\uc758\uc2e0\uccad\uc774\ub098 \ud589\uc815\uc18c\uc1a1 \ub4f1 \uc77c\ubc18\uc801\uc778 \ubd88\ubcf5\uc808\ucc28\ub97c \ud1b5\ud574 \ub2e4\ud234 \uc218 \uc788\ub2e4"],t.s)
B.a9y=s(["\uc2dc\uc815\uba85\ub839\uc5d0 \ub300\ud55c \ubd88\ubcf5\uc808\ucc28"],t.s)
B.aps=new A.b("gen_clause_review_effect_2","economic_law","\uc57d\uad00 \uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28","\uc2dc\uc815\uc870\uce58\uc758 \ud6a8\ub825\xb7\ubd88\ubcf5\uc808\ucc28","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc57d\uad00 \uc2dc\uc815\uba85\ub839\uc5d0 \ubd88\ubcf5\ud558\ub294 \uc0ac\uc5c5\uc790\uac00 \ucde8\ud560 \uc218 \uc788\ub294 \uc808\ucc28\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a4J,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc57d\uad00 \uc2dc\uc815\uba85\ub839\ub3c4 \ud558\ub098\uc758 \ud589\uc815\ucc98\ubd84\uc5d0 \ud574\ub2f9\ud558\ubbc0\ub85c, \uc774\uc5d0 \ubd88\ubcf5\ud558\ub294 \uc0ac\uc5c5\uc790\ub294 \uc77c\ubc18\uc801\uc778 \ubd88\ubcf5\uc808\ucc28\uc778 \uc774\uc758\uc2e0\uccad\uc774\ub098 \ud589\uc815\uc18c\uc1a1 \ub4f1\uc744 \ud1b5\ud574 \ub2e4\ud234 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud589\uc815\ucc98\ubd84\uc5d0 \ub300\ud55c \uc77c\ubc18 \ubc95\ub9ac\uc5d0 \ubd80\ud569\ud55c\ub2e4.",B.aam,B.a9y,null)
B.WP=s([u.fE,"\uc2dc\uc815\uc870\uce58\uac00 \ub0b4\ub824\uc9c0\uba74 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc774 \uc790\ub3d9\uc73c\ub85c \uc18c\uba78\ud55c\ub2e4","\uc2dc\uc815\uc870\uce58\uc640 \uc190\ud574\ubc30\uc0c1\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc808\ucc28\uc774\ub2e4","\uc2dc\uc815\uc870\uce58\uac00 \uc788\uc73c\uba74 \uace0\uac1d\uc740 \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \uc808\ub300\uc801 \uc6d0\uce59\uc774\ub2e4","\uc190\ud574\ubc30\uc0c1 \uccad\uad6c\ub294 \uc2dc\uc815\uc870\uce58\uac00 \ud655\uc815\ub41c \uc774\ud6c4\uc5d0\ub9cc \uac00\ub2a5\ud558\ub2e4\ub294 \uac83\uc774 \uc808\ub300\uc801 \uc6d0\uce59\uc774\ub2e4"],t.s)
B.aeg=s([u.fE],t.s)
B.a16=s(["\uc2dc\uc815\uc808\ucc28\uc640 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc758 \uad00\uacc4"],t.s)
B.akx=new A.b("gen_clause_review_effect_3","economic_law","\uc57d\uad00 \uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28","\uc2dc\uc815\uc870\uce58\uc758 \ud6a8\ub825\xb7\ubd88\ubcf5\uc808\ucc28","\uc57d\uad00 \uc2dc\uc815\uc808\ucc28\uc640 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.WP,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc2dc\uc815\uc870\uce58\ub294 \ud589\uc815\uc801 \uc81c\uc7ac\ub97c \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \uac83\uc73c\ub85c, \uc2dc\uc815\uc870\uce58\uac00 \ub0b4\ub824\uc84c\ub294\uc9c0 \uc5ec\ubd80\uc640\ub294 \ubcc4\uac1c\ub85c \ubd88\uacf5\uc815\uc57d\uad00\uc870\ud56d\uc73c\ub85c \uc778\ud574 \uc2e4\uc81c \ud53c\ud574\ub97c \uc785\uc740 \uace0\uac1d\uc740 \ubbfc\uc0ac\uc0c1 \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\uc73c\uba70, \ub450 \uc808\ucc28\ub294 \ubcd1\uc874\ud560 \uc218 \uc788\ub2e4.",B.aeg,B.a16,null)
B.a8F=s([u.BU,"\uc2dc\uc815\uc870\uce58\ub97c \ubc1b\uc544\ub3c4 \uc5b4\ub5a0\ud55c \ud6c4\uc18d \ubb38\uc81c\ub3c4 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\uc2dc\uc815\uc870\uce58\ub294 \uac00\ub9f9\uacc4\uc57d\uc11c\uc640 \uc804\ud600 \ubb34\uad00\ud558\ub2e4\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\uc2dc\uc815\uc870\uce58\ub97c \ubc1b\uc73c\uba74 \uac00\ub9f9\uacc4\uc57d\uc774 \uc790\ub3d9\uc73c\ub85c \uc804\ubd80 \ubb34\ud6a8\uac00 \ub41c\ub2e4\uace0\ub9cc \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\uc2dc\uc815\uc870\uce58 \uad00\ub828 \ub9ac\uc2a4\ud06c\ub294 \uc790\ubb38\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4"],t.s)
B.XJ=s([u.BU],t.s)
B.jw=s(["\uac00\ub9f9\ubcf8\ubd80 \uc790\ubb38 \uc2dc \uc720\uc758\uc0ac\ud56d"],t.s)
B.asU=new A.b("gen_clause_review_effect_4","economic_law","\uc57d\uad00 \uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28","\uc2dc\uc815\uc870\uce58\uc758 \ud6a8\ub825\xb7\ubd88\ubcf5\uc808\ucc28","\uac00\ub9f9\uac70\ub798\uc0ac\uac00 \uac00\ub9f9\ubcf8\ubd80\uc5d0 \uc57d\uad00(\uac00\ub9f9\uacc4\uc57d\uc11c) \uc2dc\uc815 \uad00\ub828 \ub9ac\uc2a4\ud06c\ub97c \uc790\ubb38\ud560 \ub54c \uac15\uc870\ud574\uc57c \ud560 \uc0ac\ud56d\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a8F,0,"\uac00\ub9f9\uac70\ub798\uc0ac\ub294 \uac00\ub9f9\ubcf8\ubd80\uc5d0 \uc790\ubb38\ud560 \ub54c, \uac00\ub9f9\uacc4\uc57d\uc11c(\uc57d\uad00) \uc870\ud56d\uc774 \uc2dc\uc815\uc870\uce58\ub97c \ubc1b\uc73c\uba74 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ud589\uc815\uc801 \uc81c\uc7ac\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0 \uac1c\ubcc4 \uac00\ub9f9\uc810\uacfc\uc758 \ubbfc\uc0ac\uc0c1 \uc190\ud574\ubc30\uc0c1 \ubd84\uc7c1 \ub4f1 \ucd94\uac00\uc801\uc778 \ub9ac\uc2a4\ud06c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \ud568\uaed8 \uc548\ub0b4\ud558\uc5ec \uc885\ud569\uc801\uc778 \ub9ac\uc2a4\ud06c \uad00\ub9ac\ub97c \ub3d5\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4.",B.XJ,B.jw,null)
B.a_M=s([u.zE,"\uc624\uc9c1 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc758 \uac1c\uc778 \uc2e0\uc0c1 \uc815\ubcf4\ub9cc \ucd9c\uc81c\ub41c\ub2e4","\uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28\uc640 \ubb34\uad00\ud55c \uc138\ubc95 \uaddc\uc815\ub9cc \ucd9c\uc81c\ub41c\ub2e4","\uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28 \uad00\ub828 \ubb38\uc81c\ub294 \uc804\ud600 \ucd9c\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc624\uc9c1 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uccad\uc0ac\uc758 \uc704\uce58\ub9cc \ubb3b\ub294 \ubb38\uc81c\ub9cc \ucd9c\uc81c\ub41c\ub2e4"],t.s)
B.a0f=s([u.zE],t.s)
B.anZ=new A.b("gen_clause_review_exam_1","economic_law","\uc57d\uad00 \uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28","\uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28 \uad00\ub828 \uc2dc\ud5d8 \ud3ec\uc778\ud2b8","\uac00\ub9f9\uac70\ub798\uc0ac \uc2dc\ud5d8\uc5d0\uc11c \uc57d\uad00 \uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28 \uad00\ub828 \ubb38\uc81c\uac00 \uc790\uc8fc \ub2e4\ub8e8\ub294 \ud575\uc2ec \ud3ec\uc778\ud2b8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a_M,0,"\uc57d\uad00 \uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28 \uad00\ub828 \ubb38\uc81c\ub294 \uc2ec\uc0ac\uccad\uad6c\uad8c\uc790\uc640 \uc9c1\uad8c\uc2ec\uc0ac\uc758 \uc778\uc815, \uc2dc\uc815\uad8c\uace0\uc640 \uc2dc\uc815\uba85\ub839\uc758 \uad6c\ubcc4, \uadf8\ub9ac\uace0 \uc2dc\uc815\uc870\uce58\uac00 \uac1c\ubcc4 \uacc4\uc57d\uc758 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uc774\ub098 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uacfc \uc5b4\ub5a4 \uad00\uacc4\ub97c \uac16\ub294\uc9c0\ub77c\ub294 \ud575\uc2ec \ucd95\uc744 \uc911\uc2ec\uc73c\ub85c \ucd9c\uc81c\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.",B.a0f,B.bc,null)
B.J8=s([u.jT,"\ub450 \ud30c\ud2b8\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \ub0b4\uc6a9\uc744 \ub2e4\ub8e8\uc5b4 \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28 \ud30c\ud2b8\ub294 \ubb34\ud6a8\uc0ac\uc720\uc640 \uc804\ud600 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \ubc95\ub960\uc5d0 \uadfc\uac70\ud55c\ub2e4","\ubb34\ud6a8\uc0ac\uc720 \ud30c\ud2b8\ub9cc \uc2dc\ud5d8\uc5d0 \ucd9c\uc81c\ub418\uace0 \uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28\ub294 \ucd9c\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28\ub294 \ud615\uc0ac\uc808\ucc28\ub9cc\uc744 \ub2e4\ub8e8\ub294 \ud30c\ud2b8\uc774\ub2e4"],t.s)
