B.Qh=s(["\uc704\ubc18\uc0ac\uc5c5\uc790\uac00 \uc870\uc0ac\uc5d0 \uc801\uadf9 \ud611\uc870\ud558\uace0 \uc790\uc9c4\ud558\uc5ec \uc2dc\uc815\ud55c \uacbd\uc6b0","\uc704\ubc18\uc0ac\uc5c5\uc790\uac00 \uc870\uc0ac\ub97c \ubc29\ud574\ud558\uace0 \uc99d\uac70\ub97c \uc778\uba78\ud55c \uacbd\uc6b0","\uc704\ubc18\ud589\uc704\ub97c \ubc18\ubcf5\uc801\uc73c\ub85c \uc7ac\ubc94\ud55c \uacbd\uc6b0","\uc704\ubc18\ud589\uc704\ub85c \uc5bb\uc740 \uc774\uc775\uc758 \uaddc\ubaa8\uac00 \ub9e4\uc6b0 \ud070 \uacbd\uc6b0","\uc704\ubc18\ud589\uc704\uac00 \uad11\ubc94\uc704\ud55c \uc9c0\uc5ed\uc5d0 \uac78\uccd0 \uc774\ub8e8\uc5b4\uc9c4 \uacbd\uc6b0"],t.s)
B.W9=s(["\uc704\ubc18\uc0ac\uc5c5\uc790\uac00 \uc870\uc0ac\uc5d0 \uc801\uadf9 \ud611\uc870\ud558\uace0 \uc790\uc9c4\ud558\uc5ec \uc2dc\uc815\ud55c \uacbd\uc6b0"],t.s)
