B.Xu=s(["\ubd88\ubcf5\uc808\ucc28 \uc790\ubb38 \uc2dc \uc720\uc758\uc0ac\ud56d"],t.s)
B.atR=new A.b("gen_appeal_exam_3","economic_law","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uac00\ub9f9\uac70\ub798\uc0ac\uac00 \uc2dc\uc815\uba85\ub839\xb7\uacfc\uc9d5\uae08 \ucc98\ubd84\uc744 \ubc1b\uc740 \uac00\ub9f9\ubcf8\ubd80\uc5d0 \ubd88\ubcf5\uc808\ucc28\ub97c \uc790\ubb38\ud560 \ub54c \uac15\uc870\ud574\uc57c \ud560 \uc0ac\ud56d\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.KX,0,"\uac00\ub9f9\uac70\ub798\uc0ac\ub294 \ucc98\ubd84\uc744 \ubc1b\uc740 \uac00\ub9f9\ubcf8\ubd80\uc5d0\uac8c \uc774\uc758\uc2e0\uccad\uacfc \ud589\uc815\uc18c\uc1a1(\ucde8\uc18c\uc18c\uc1a1) \uac01\uac01\uc758 \uc808\ucc28\uc801 \ud2b9\uc131(\uc81c\uae30 \uae30\uac04, \uad00\ud560, \uc804\uce58 \uc5ec\ubd80)\uc744 \uc815\ud655\ud788 \uc548\ub0b4\ud558\uc5ec, \uc815\ud574\uc9c4 \uae30\uac04 \ub0b4\uc5d0 \uc801\uc808\ud55c \ubd88\ubcf5 \uc218\ub2e8\uc744 \ub193\uce58\uc9c0 \uc54a\uace0 \ud65c\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \ub3d5\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4.",B.a2E,B.Xu,null)
B.a2Y=s([u.u2,"\ubd88\ubcf5\uc808\ucc28\ub294 \uc0ac\uc5c5\uc790\uc5d0\uac8c \ubd88\uc774\uc775\ub9cc \uc8fc\uae30 \uc704\ud55c \uac83\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\ubd88\ubcf5\uc808\ucc28 \uc815\ube44\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc5c5\ubb34\ub97c \uc904\uc774\uae30 \uc704\ud55c \uac83\uc77c \ubfd0\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\ubd88\ubcf5\uc808\ucc28\ub294 \uc2e4\uc9c8\uc801\uc778 \uc815\ucc45\uc801 \ud6a8\uc6a9\uc774 \uc804\ud600 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4","\ubd88\ubcf5\uc808\ucc28\ub294 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c \ud655\uc815\uc744 \uc704\ud55c \uac83\uc774\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
