B.a5A=s(["\ubd88\ubcf5\uc808\ucc28 \uc815\ube44\uc758 \uc815\ucc45\uc801 \uc774\uc720"],t.s)
B.aox=new A.b("gen_appeal_exam_4","economic_law","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \ucc98\ubd84\uc5d0 \ub300\ud55c \ubd88\ubcf5\uc808\ucc28\uac00 \uc2e0\uc18d\ud558\uac8c \uc815\ube44\ub418\uc5b4\uc57c \ud558\ub294 \uc815\ucc45\uc801 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a2Y,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08 \ub4f1 \ucc98\ubd84\uc740 \uc0ac\uc5c5\uc790\uc758 \uc601\uc5c5\ud65c\ub3d9\uacfc \uc2dc\uc7a5\uc5d0\uc11c\uc758 \uc9c0\uc704\uc5d0 \uc0c1\ub2f9\ud55c \uc601\ud5a5\uc744 \ubbf8\uce60 \uc218 \uc788\uc73c\ubbc0\ub85c, \ucc98\ubd84\uc5d0 \ubd88\ubcf5\ud558\ub294 \uc0ac\uc5c5\uc790\uac00 \uc2e0\uc18d\ud558\uace0 \uc2e4\ud6a8\uc801\uc73c\ub85c \uad8c\ub9ac\ub97c \uad6c\uc81c\ubc1b\uc744 \uc218 \uc788\ub3c4\ub85d \uc774\uc758\uc2e0\uccad\xb7\ud589\uc815\uc18c\uc1a1 \ub4f1\uc758 \ubd88\ubcf5\uc808\ucc28\ub97c \uccb4\uacc4\uc801\uc73c\ub85c \uc815\ube44\ud560 \ud544\uc694\uac00 \uc788\ub2e4\ub294 \uac83\uc774 \uc815\ucc45\uc801 \uc774\uc720\uc774\ub2e4.",B.TQ,B.a5A,null)
B.a2R=s([u.u4,"\ub450 \ud30c\ud2b8\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \ub0b4\uc6a9\uc744 \ub2e4\ub8e8\uc5b4 \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\ub294 \uc870\uc0ac\uc808\ucc28\uc640 \uc804\ud600 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \ubc95\ub960\uc5d0 \uadfc\uac70\ud55c\ub2e4","\uc870\uc0ac\uc808\ucc28\ub9cc \uc2dc\ud5d8\uc5d0 \ucd9c\uc81c\ub418\uace0 \uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\ub294 \ucd9c\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\ub294 \ud615\uc0ac\uc808\ucc28\ub9cc\uc744 \ub2e4\ub8e8\ub294 \ud30c\ud2b8\uc774\ub2e4"],t.s)
B.Zc=s([u.u4],t.s)
B.adx=s(["\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\uc640 \uc870\uc0ac\uc808\ucc28\uc758 \uad00\uacc4"],t.s)
B.as_=new A.b("gen_appeal_exam_5","economic_law","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\uc640 \uc870\uc0ac\uc808\ucc28\xb7\ucc98\ubd84\uc2dc\ud6a8 \ud30c\ud2b8\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a2R,0,"\uc870\uc0ac\uc808\ucc28 \ud30c\ud2b8\uac00 \uc2e0\uace0\xb7\uc778\uc9c0\ubd80\ud130 \uc2ec\uc758\xb7\ucc98\ubd84\uc5d0 \uc774\ub974\uae30\uae4c\uc9c0\uc758 \uacfc\uc815\uc744 \ub2e4\ub8ec\ub2e4\uba74, \uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28 \ud30c\ud2b8\ub294 \uadf8 \ucc98\ubd84\uc774 \ub0b4\ub824\uc9c4 \uc774\ud6c4 \ucc98\ubd84\uc758 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \ub2e4\ud22c\ub294 \uad8c\ub9ac\uad6c\uc81c \uc808\ucc28\ub97c \ub2e4\ub8ec\ub2e4\ub294 \uc810\uc5d0\uc11c, \ub450 \ud30c\ud2b8\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc0ac\uac74 \ucc98\ub9ac\uc758 \uc804\uccb4 \ud750\ub984\uc5d0\uc11c \uc55e\ub4a4\ub97c \uc774\ub8e8\ub294 \ubcf4\uc644\uc801 \uad00\uacc4\uc5d0 \uc788\ub2e4.",B.Zc,B.adx,null)
B.a1n=s([u.B0,"\uc99d\uba85\ucc45\uc784\uc740 \ud56d\uc0c1 \ucc98\ubd84\uc744 \ub2e4\ud22c\ub294 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc788\ub2e4","\uc99d\uba85\ucc45\uc784\uc740 \uc18c\ube44\uc790\ub2e8\uccb4\uc5d0\uac8c \uc788\ub2e4","\ucde8\uc18c\uc18c\uc1a1\uc5d0\ub294 \uc99d\uba85\ucc45\uc784\uc774\ub77c\ub294 \uac1c\ub150 \uc790\uccb4\uac00 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc99d\uba85\ucc45\uc784\uc740 \uc624\uc9c1 \ubc95\uc6d0\uc758 \uc7ac\ub7c9\uc73c\ub85c\ub9cc \uacb0\uc815\ub41c\ub2e4"],t.s)
B.QB=s([u.B0],t.s)
B.Id=s(["\ucde8\uc18c\uc18c\uc1a1\uc758 \uc99d\uba85\ucc45\uc784"],t.s)
B.anS=new A.b("gen_appeal_exam_6","economic_law","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\uc5d0\uc11c \uc99d\uba85\ucc45\uc784\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a1n,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \ucc98\ubd84\uc5d0 \ub300\ud55c \ucde8\uc18c\uc18c\uc1a1\uc5d0\uc11c, \ucc98\ubd84\uc758 \uc801\ubc95\uc131(\uc704\ubc18\uc0ac\uc2e4\uc758 \uc874\uc7ac, \ucc98\ubd84\uc758 \uc815\ub2f9\uc131 \ub4f1)\uc5d0 \ub300\ud55c \uc99d\uba85\ucc45\uc784\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ucc98\ubd84\uc744 \ub0b4\ub9b0 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ubd80\ub2f4\ud558\ub294 \uac83\uc774 \ud589\uc815\uc18c\uc1a1\uc758 \uc77c\ubc18\uc801\uc778 \uc99d\uba85\ucc45\uc784 \ubd84\ubc30 \uc6d0\uce59\uc5d0 \ubd80\ud569\ud55c\ub2e4.",B.QB,B.Id,null)
