B.ap8=new A.b("gen_predatory_def_6","economic_law","\ubd80\ub2f9\uc5fc\ub9e4\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c","\ubd80\ub2f9\uc5fc\ub9e4\uc758 \uc758\ubbf8\xb7\ud310\ub2e8\uae30\uc900","\uc628\ub77c\uc778 \ud50c\ub7ab\ud3fc \uc0ac\uc5c5\uc790\uac00 \uc2dc\uc7a5 \ucd08\uae30 \uc810\uc720\uc728 \ud655\ubcf4\ub97c \uc704\ud574 \uc7a5\uae30\uac04 \uc6d0\uac00 \uc774\ud558\ub85c \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud558\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Zd,0,"\uc628\ub77c\uc778 \ud50c\ub7ab\ud3fc \uc0ac\uc5c5\uc790\uac00 \ucd08\uae30 \uc810\uc720\uc728 \ud655\ubcf4\ub97c \uba85\ubaa9\uc73c\ub85c \uc7a5\uae30\uac04 \uc6d0\uac00 \uc774\ud558\ub85c \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud558\ub294 \uacbd\uc6b0, \uadf8\uac83\uc774 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \uc2dc\uc7a5\uc5d0\uc11c \ubc30\uc81c\ud560 \uc6b0\ub824\uac00 \uc788\uc744 \uc815\ub3c4\ub85c \uc9c0\uc18d\ub418\uace0 \uc788\ub294\uc9c0, \ud5a5\ud6c4 \ub3c5\uc810\uc801 \uc9c0\uc704\ub97c \uc774\uc6a9\ud55c \uac00\uaca9 \uc778\uc0c1 \ub4f1\uc758 \ubaa9\uc801\uc774 \uc788\ub294\uc9c0\uc5d0 \ub530\ub77c \ubd80\ub2f9\uc5fc\ub9e4\uc5d0 \ud574\ub2f9\ud560 \uc18c\uc9c0\uac00 \uc788\uc5b4 \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4.",B.a__,B.a9U,null)
B.UQ=s([u.gI,"\uc2dc\uc7a5\uac00\uaca9\uc5d0 \ub9de\ucd94\uc5b4 \uc815\uc0c1\uc801\uc73c\ub85c \uc0c1\ud488\uc744 \ub9e4\uc785\ud558\ub294 \ud589\uc704","\uacbd\uc7c1\uc785\ucc30\uc744 \ud1b5\ud574 \ucd5c\uc800\uac00\ub85c \uc0c1\ud488\uc744 \ub9e4\uc785\ud558\ub294 \ud589\uc704","\uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \ub0ae\uc740 \uac00\uaca9\uc744 \uc694\uad6c\ud558\ub294 \ud589\uc704","\uc18c\ube44\uc790\ub85c\ubd80\ud130 \uc911\uace0\ud488\uc744 \ub9e4\uc785\ud558\ub294 \ud589\uc704"],t.s)
