B.ar0=new A.b("gen_predatory_exam_3","economic_law","\ubd80\ub2f9\uc5fc\ub9e4\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc2dc\ud5d8 \ud3ec\uc778\ud2b8","\uac00\ub9f9\uac70\ub798\uc0ac \uc2dc\ud5d8\uc5d0\uc11c \ubd80\ub2f9\uc5fc\ub9e4\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c \uad00\ub828 \ubb38\uc81c\uac00 \uc790\uc8fc \ub2e4\ub8e8\ub294 \ud575\uc2ec \ud3ec\uc778\ud2b8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a1i,0,"\ubd80\ub2f9\uc5fc\ub9e4\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c \uad00\ub828 \ubb38\uc81c\ub294 \ubd80\ub2f9\uc5fc\ub9e4\uc758 \uac1c\ub150\uacfc \ud310\ub2e8\uae30\uc900, \ubd80\ub2f9\uace0\uac00\ub9e4\uc785\uacfc\uc758 \uacf5\ud1b5\uc810(\uac00\uaca9\uc744 \uc774\uc6a9\ud55c \uacbd\uc7c1\uc0ac\uc5c5\uc790 \ubc30\uc81c), \uadf8\ub9ac\uace0 \ud1b5\uc0c1\uc801\uc778 \uac00\uaca9 \ud560\uc778\xb7\uc7ac\uace0 \ucc98\ubd84 \ud310\ub9e4\uc640\uc758 \uad6c\ubcc4\uc774\ub77c\ub294 \ud575\uc2ec \ucd95\uc744 \uc911\uc2ec\uc73c\ub85c \ucd9c\uc81c\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.",B.a1K,B.bc,null)
B.Ln=s(["\ub2e8\uc21c\ud55c \uac00\uaca9 \ud560\uc778\uc774\ub098 \uc7ac\uace0 \ucc98\ubd84 \ud310\ub9e4\ub97c \ubd80\ub2f9\uc5fc\ub9e4\uc640 \ub3d9\uc77c\uc2dc\ud558\ub294 \uc120\ud0dd\uc9c0","\uac00\ub9f9\uacc4\uc57d\uc11c\uc758 \ud3f0\ud2b8 \ud06c\uae30\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uccad\uc0ac\uc758 \uce35\uc218\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0","\uc704\uc6d0\uc7a5\uc758 \uac1c\uc778 \ucde8\ubbf8\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0","\uc2ec\uc0ac\uccad\uad6c \uc811\uc218 \ucc3d\uad6c\uc758 \uc8fc\uc18c\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0"],t.s)
B.KD=s(["\ub2e8\uc21c\ud55c \uac00\uaca9 \ud560\uc778\uc774\ub098 \uc7ac\uace0 \ucc98\ubd84 \ud310\ub9e4\ub97c \ubd80\ub2f9\uc5fc\ub9e4\uc640 \ub3d9\uc77c\uc2dc\ud558\ub294 \uc120\ud0dd\uc9c0"],t.s)
B.aqI=new A.b("gen_predatory_exam_4","economic_law","\ubd80\ub2f9\uc5fc\ub9e4\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc2dc\ud5d8 \ud3ec\uc778\ud2b8","\ubd80\ub2f9\uc5fc\ub9e4 \uad00\ub828 \ubb38\uc81c\uc5d0\uc11c \uc790\uc8fc \ucd9c\uc81c\ub418\ub294 \ud568\uc815 \uc720\ud615\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Ln,0,'\ubd80\ub2f9\uc5fc\ub9e4 \ubb38\uc81c\uc5d0\uc11c\ub294 \uc77c\uc2dc\uc801\uc778 \uac00\uaca9 \ud560\uc778\uc774\ub098 \uc7ac\uace0 \ucc98\ubd84\uc744 \uc704\ud55c \ud1b5\uc0c1\uc801\uc778 \ud310\ub9e4\ud589\uc704\ub97c \ubd80\ub2f9\uc5fc\ub9e4\uc640 \ub3d9\uc77c\uc2dc\ud558\ub294 \uc120\ud0dd\uc9c0\uac00 \ud568\uc815\uc73c\ub85c \uc790\uc8fc \ucd9c\uc81c\ub418\ubbc0\ub85c, \ube44\uc6a9 \uc774\ud558 \uac00\uaca9\uc758 "\uacc4\uc18d\uc131"\uacfc \uacbd\uc7c1\uc0ac\uc5c5\uc790 \ubc30\uc81c\uc758 "\uc6b0\ub824"\ub77c\ub294 \uc694\uac74\uc744 \uc815\ud655\ud788 \uad6c\ubcc4\ud574 \ub450\uc5b4\uc57c \ud55c\ub2e4.',B.KD,B.ct,null)
B.WZ=s([u.Er,"\uac00\uaca9\uc744 \ub0ae\ucd94\ub294 \uc804\ub7b5\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\ubd80\ub2f9\uc5fc\ub9e4 \uaddc\uc81c\ub294 \uac00\ub9f9\ubcf8\ubd80\uc640 \uc804\ud600 \ubb34\uad00\ud558\ub2e4\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\uac00\uaca9 \uc804\ub7b5\uc740 \uc790\ubb38\ud560 \ud544\uc694\uac00 \uc5c6\ub294 \uc0ac\ud56d\uc774\ub77c\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\uc6d0\uac00 \uc774\ud558 \uac00\uaca9\uc740 \ud56d\uc0c1 \uc18c\ube44\uc790 \uc774\uc775\uc744 \uc704\ud55c \uac83\uc774\ubbc0\ub85c \ubb38\uc81c\uc5c6\ub2e4\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4"],t.s)
