B.Yy=s(["2\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790\uc758 \uac10\uba74 \uc218\uc900"],t.s)
B.apx=new A.b("gen_leniency_intro_3","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\uc81c\ub3c4\uc758 \ucde8\uc9c0\xb7\uac10\uba74 \uc694\uac74","2\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790(\uc870\uc0ac \ud611\uc870\uc790)\uc5d0\uac8c \uc778\uc815\ub418\ub294 \uac10\uba74 \ud61c\ud0dd\uc758 \uc77c\ubc18\uc801 \uc218\uc900\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.acs,0,"\ud574\ub2f9 \uacf5\ub3d9\ud589\uc704\ub97c \uc785\uc99d\ud558\ub294 \ub370 \ud544\uc694\ud55c \uc99d\uac70\ub97c 2\ubc88\uc9f8\ub85c \uc81c\uacf5\ud558\uace0 \uc870\uc0ac\uc5d0 \ud611\uc870\ud558\ub294 \ub4f1 \uc694\uac74\uc744 \uac16\ucd98 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub294, 1\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790(\uc804\ubd80 \uba74\uc81c)\ubcf4\ub2e4\ub294 \ub0ae\uc740 \uc218\uc900\uc774\uc9c0\ub9cc \uc77c\uc815 \ube44\uc728(\uc608: \uacfc\uc9d5\uae08 \uc77c\ubd80 \uac10\uacbd)\uc758 \uac10\uba74 \ud61c\ud0dd\uc774 \uc778\uc815\ub420 \uc218 \uc788\ub2e4.",B.adb,B.Yy,null)
B.a9T=s([u.mz,"\uc870\uc0ac \ucd08\uae30\uc5d0\ub9cc \ud611\uc870\ud558\uace0 \uc774\ud6c4\uc5d0\ub294 \ud611\uc870\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub418\ub294 \uac83","\uc870\uc0ac\uad00\uacfc \uac1c\uc778\uc801\uc778 \uce5c\ubd84\uc744 \uc313\ub294 \uac83","\uc870\uc0ac\uc640 \ubb34\uad00\ud55c \uc790\ub8cc\ub97c \ub300\ub7c9\uc73c\ub85c \uc81c\ucd9c\ud558\ub294 \uac83","\uc870\uc0ac\uc5d0 \ud611\uc870\ud55c\ub2e4\ub294 \ub9d0\ub9cc \ud558\uace0 \uc2e4\uc81c \ud589\ub3d9\uc740 \ud558\uc9c0 \uc54a\ub294 \uac83"],t.s)
B.X0=s([u.mz],t.s)
B.KS=s(["\uc131\uc2e4 \ud611\uc870 \uc694\uac74\uc758 \uc758\ubbf8"],t.s)
B.amo=new A.b("gen_leniency_intro_4","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\uc81c\ub3c4\uc758 \ucde8\uc9c0\xb7\uac10\uba74 \uc694\uac74",'\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74 \uc694\uac74 \uc911 "\uc870\uc0ac \uc885\ub8cc \uc2dc\uae4c\uc9c0 \uc131\uc2e4\ud558\uac8c \ud611\uc870"\ud55c\ub2e4\ub294 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.a9T,0,'"\uc870\uc0ac\uac00 \ub05d\ub0a0 \ub54c\uae4c\uc9c0 \uc131\uc2e4\ud558\uac8c \ud611\uc870"\ud55c\ub2e4\ub294 \uc694\uac74\uc740, \uc790\uc9c4\uc2e0\uace0\uc790\uac00 \uc790\uc2e0\uc774 \uc54c\uace0 \uc788\ub294 \uacf5\ub3d9\ud589\uc704 \uad00\ub828 \uc0ac\uc2e4\uc744 \uc9c0\uccb4 \uc5c6\uc774 \uc9c4\uc220\ud558\uace0 \ud544\uc694\ud55c \uc790\ub8cc\ub97c \uc81c\ucd9c\ud558\ub294 \ub4f1 \uc870\uc0ac\uc5d0 \uc2e4\uc9c8\uc801\uc73c\ub85c \ub3c4\uc6c0\uc774 \ub418\ub294 \ubc29\uc2dd\uc73c\ub85c \uc9c0\uc18d\uc801\uc73c\ub85c \ud611\ub825\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud558\uba70, \uc870\uc0ac \ucd08\ubc18\uc5d0\ub9cc \ud611\uc870\ud558\uace0 \uc774\ud6c4 \ud611\uc870\ub97c \uc911\ub2e8\ud558\uba74 \uc774 \uc694\uac74\uc744 \ucda9\uc871\ud558\uc9c0 \ubabb\ud560 \uc218 \uc788\ub2e4.',B.X0,B.KS,null)
B.Wm=s([u.uK,"\uc8fc\ub3c4\uc801 \uc0ac\uc5c5\uc790\uc77c\uc218\ub85d \uc624\ud788\ub824 \ub354 \ud070 \uac10\uba74 \ud61c\ud0dd\uc744 \ubc1b\ub294\ub2e4","\uc8fc\ub3c4 \uc5ec\ubd80\ub294 \uac10\uba74 \ud310\ub2e8\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\uc8fc\ub3c4\uc801 \uc0ac\uc5c5\uc790\ub3c4 \uc790\uc9c4\uc2e0\uace0\ub9cc \ud558\uba74 \ud56d\uc0c1 \uc804\ubd80 \uba74\uc81c\ub97c \ubc1b\ub294\ub2e4","\uc8fc\ub3c4\uc801 \uc0ac\uc5c5\uc790\ub294 \uac10\uba74\uc81c\ub3c4\uc758 \uc720\uc77c\ud55c \uc801\uc6a9 \ub300\uc0c1\uc774\ub2e4"],t.s)
B.aed=s([u.uK],t.s)
B.Wi=s(["\uc8fc\ub3c4\uc801 \uc0ac\uc5c5\uc790\uc758 \uac10\uba74 \ubc30\uc81c"],t.s)
B.ame=new A.b("gen_leniency_intro_5","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\uc81c\ub3c4\uc758 \ucde8\uc9c0\xb7\uac10\uba74 \uc694\uac74","\uc790\uc9c4\uc2e0\uace0\uc790\uac00 \ub2e4\ub978 \uc0ac\uc5c5\uc790\ub97c \uac15\uc694\ud558\uc5ec \uacf5\ub3d9\ud589\uc704\uc5d0 \ucc38\uc5ec\ud558\uac8c \ud55c \uc8fc\ub3c4\uc801 \uc0ac\uc5c5\uc790\uc778 \uacbd\uc6b0 \uac10\uba74 \uc5ec\ubd80\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Wm,0,"\ub2e4\ub978 \uc0ac\uc5c5\uc790\ub97c \uac15\uc694\ud558\uc5ec \uacf5\ub3d9\ud589\uc704\uc5d0 \ucc38\uc5ec\ud558\ub3c4\ub85d \ud558\ub294 \ub4f1 \ub2f4\ud569\uc744 \uc8fc\ub3c4\ud55c \uc0ac\uc5c5\uc790\ub294, \uc790\uc9c4\uc2e0\uace0\ub97c \ud558\ub354\ub77c\ub3c4 \uac10\uba74 \ub300\uc0c1\uc5d0\uc11c \ubc30\uc81c\ub418\uac70\ub098 \uac10\uba74 \ud61c\ud0dd\uc774 \uc81c\ud55c\ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \uc81c\ub3c4\uc758 \ucde8\uc9c0(\ub2f4\ud569 \uc8fc\ub3c4\uc790\uc5d0 \ub300\ud55c \ud2b9\ud61c \ubc29\uc9c0)\uc5d0 \ubd80\ud569\ud558\ub294 \ubc95\ub9ac\ub85c \uc774\ud574\ub41c\ub2e4.",B.aed,B.Wi,null)
B.SD=s([u.p9,"\ubaa8\ub4e0 \uc2e0\uace0\uc790\uc5d0\uac8c \uc21c\uc11c\uc640 \ubb34\uad00\ud558\uac8c \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \ud61c\ud0dd\uc744 \ubd80\uc5ec\ud558\ub294 \uad6c\uc870","\uc2e0\uace0 \uc21c\uc11c\uc640 \uad00\uacc4\uc5c6\uc774 \ubb34\uc791\uc704\ub85c \ud61c\ud0dd\uc744 \ubc30\ubd84\ud558\ub294 \uad6c\uc870","\uc2e0\uace0\ub97c \uac00\uc7a5 \ub2a6\uac8c \ud55c \uc0ac\uc5c5\uc790\uc5d0\uac8c \uac00\uc7a5 \ud070 \ud61c\ud0dd\uc744 \uc8fc\ub294 \uad6c\uc870","\uc2e0\uace0 \uc790\uccb4\ub97c \uc6d0\ucc9c\uc801\uc73c\ub85c \ucc28\ub2e8\ud558\ub294 \uad6c\uc870"],t.s)
B.Hs=s([u.p9],t.s)
