B.ajV=new A.b("gen_ta_sanction_3","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58(\uc0ac\uc5c5\uc790\ub2e8\uccb4)","\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0 \ub300\ud55c \uc2dc\uc815\uc870\uce58\uc758 \ub0b4\uc6a9\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a7G,4,'\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0 \ub300\ud55c \uc2dc\uc815\uc870\uce58\uc5d0\ub294 \uc704\ubc95\ud55c \uacb0\uc758\xb7\uc9c0\uce68\uc758 \ucde8\uc18c, \ud589\uc704\uc758 \uc911\uc9c0, \uc704\ubc18\uc0ac\uc2e4\uc758 \uacf5\ud45c, \uc7ac\ubc1c\ubc29\uc9c0\ub97c \uc704\ud55c \uc870\uce58 \ub4f1\uc774 \ud3ec\ud568\ub420 \uc218 \uc788\ub2e4. "\uc784\uc9c1\uc6d0 \uac1c\uc778\uc5d0 \ub300\ud55c \uc2e0\uccb4\uc758 \uc790\uc720 \uc81c\ud55c"\uacfc \uac19\uc740 \uc870\uce58\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ud589\uc815\uc801 \uc2dc\uc815\uc870\uce58\uc758 \ubc94\uc704\ub97c \ubc97\uc5b4\ub098\ub294 \uac83\uc73c\ub85c, \uc774\ub294 \ud615\uc0ac\uc808\ucc28\uc5d0\uc11c \ubc95\uc6d0\uc774 \uad00\uc5ec\ud560 \ubb38\uc81c\uc774\uc9c0 \uc2dc\uc815\uc870\uce58\uc758 \ub0b4\uc6a9\uc774 \ub420 \uc218 \uc5c6\ub2e4.',B.Vp,B.abA,null)
B.Ra=s([u.O,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0 \ub300\ud574\uc11c\ub294 \uc5b4\ub5a0\ud55c \uc870\uc0ac\ub3c4 \uc9c4\ud589\ud560 \uc218 \uc5c6\ub2e4","\uc870\uc0ac\ub294 \ubc18\ub4dc\uc2dc \uad6c\uc131\uc0ac\uc5c5\uc790 \uc804\uc6d0\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c\ub9cc \uac1c\uc2dc\ub420 \uc218 \uc788\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc870\uc0ac\uc5d0 \uc804\ud600 \ud611\uc870\ud560 \uc758\ubb34\uac00 \uc5c6\ub2e4","\uc870\uc0ac \uacb0\uacfc\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \uc2dc\uc815\uc870\uce58\uac00 \ub0b4\ub824\uc9c4\ub2e4"],t.s)
B.aer=s([u.O],t.s)
B.a1o=s(["\uc870\uc0ac\uc808\ucc28"],t.s)
B.alz=new A.b("gen_ta_sanction_4","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58(\uc0ac\uc5c5\uc790\ub2e8\uccb4)","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704 \uc870\uc0ac \uc808\ucc28\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Ra,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc5d0 \ub300\ud574\uc11c\ub3c4 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ub97c \uac1c\uc2dc\ud558\uac70\ub098, \uc774\ud574\uad00\uacc4\uc778\uc758 \uc2e0\uace0\ub97c \uacc4\uae30\ub85c \uc870\uc0ac\ub97c \uc9c4\ud589\ud560 \uc218 \uc788\ub2e4. \uc870\uc0ac\uc5d0 \uad6c\uc131\uc0ac\uc5c5\uc790 \uc804\uc6d0\uc758 \ub3d9\uc758\uac00 \ud544\uc694\ud55c \uac83\uc740 \uc544\ub2c8\uba70, \uc870\uc0ac \uacb0\uacfc \uc704\ubc18\uc0ac\uc2e4\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\uc73c\uba74 \uc2dc\uc815\uc870\uce58\uac00 \ub0b4\ub824\uc9c0\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4.",B.aer,B.a1o,null)
B.a5Y=s(["\ud574\ub2f9 \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc774\uc758\uc2e0\uccad\uc774\ub098 \ud589\uc815\uc18c\uc1a1 \ub4f1\uc744 \ud1b5\ud574 \ucc98\ubd84\uc5d0 \ubd88\ubcf5\ud560 \uc218 \uc788\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ucc98\ubd84\uc5d0 \ubd88\ubcf5\ud560 \uc218 \uc5c6\ub2e4","\ubd88\ubcf5\uc740 \uc624\uc9c1 \uad6c\uc131\uc0ac\uc5c5\uc790 \uac1c\uc778\ub9cc \uc81c\uae30\ud560 \uc218 \uc788\uace0 \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \ubd88\ubcf5\ud560 \uc218 \uc5c6\ub2e4","\ucc98\ubd84\uc5d0 \ub300\ud55c \ubd88\ubcf5\uc740 \ud615\uc0ac\uc7ac\ud310\uc744 \ud1b5\ud574\uc11c\ub9cc \uac00\ub2a5\ud558\ub2e4","\ubd88\ubcf5\uc808\ucc28\ub294 \uc815\ubd80\uc758 \uc7ac\ub7c9\uc73c\ub85c \uc644\uc804\ud788 \ubc30\uc81c\ub420 \uc218 \uc788\ub2e4"],t.s)
B.Ui=s(["\ud574\ub2f9 \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc774\uc758\uc2e0\uccad\uc774\ub098 \ud589\uc815\uc18c\uc1a1 \ub4f1\uc744 \ud1b5\ud574 \ucc98\ubd84\uc5d0 \ubd88\ubcf5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.akE=new A.b("gen_ta_sanction_5","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58(\uc0ac\uc5c5\uc790\ub2e8\uccb4)","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc5d0 \ub300\ud55c \uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08 \ucc98\ubd84\uc5d0 \ubd88\ubcf5\ud558\ub294 \uc808\ucc28\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a5Y,0,"\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc5d0 \ub300\ud55c \uc2dc\uc815\uc870\uce58\ub098 \uacfc\uc9d5\uae08 \ucc98\ubd84\uc5d0 \uc774\uc758\uac00 \uc788\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294, \ub2e4\ub978 \uacf5\uc815\uac70\ub798\ubc95 \uc704\ubc18 \ucc98\ubd84\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc774\uc758\uc2e0\uccad\uc774\ub098 \ud589\uc815\uc18c\uc1a1\uc744 \ud1b5\ud574 \uadf8 \ucc98\ubd84\uc758 \ucde8\uc18c\xb7\ubcc0\uacbd\uc744 \uad6c\ud560 \uc218 \uc788\ub2e4.",B.Ui,B.o1,null)
B.a7c=s([u.aj,"\uad6c\uc131\uc0ac\uc5c5\uc790\uc5d0\uac8c \ucc45\uc784\uc744 \ubb3b\ub294 \uac83\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \ucc45\uc784\uc744 \uc644\uc804\ud788 \ub300\uccb4\ud558\uae30 \uc704\ud568\uc774\ub2e4","\uad6c\uc131\uc0ac\uc5c5\uc790\uc5d0 \ub300\ud55c \ucc45\uc784 \ucd94\uad81\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uc81c\ub3c4\uc758 \uc2e4\ud6a8\uc131\uacfc \ubb34\uad00\ud558\ub2e4","\uc774\ub294 \uc624\ub85c\uc9c0 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc7ac\uc815 \ubd80\ub2f4\uc744 \uc904\uc774\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\uad6c\uc131\uc0ac\uc5c5\uc790 \ucc45\uc784\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uac00 \ud574\uc0b0\ub41c \uacbd\uc6b0\uc5d0\ub9cc \ubb38\uc81c\ub41c\ub2e4"],t.s)
B.a_z=s([u.aj],t.s)
B.aab=s(["\uad6c\uc131\uc0ac\uc5c5\uc790 \ucc45\uc784 \ucd94\uad81\uc758 \ucde8\uc9c0"],t.s)
B.al2=new A.b("gen_ta_sanction_6","economic_law","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58(\uc0ac\uc5c5\uc790\ub2e8\uccb4)","\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704 \uaddc\uc81c\uc758 \uc2e4\ud6a8\uc131\uc744 \ub192\uc774\uae30 \uc704\ud574 \uad6c\uc131\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub3c4 \ucc45\uc784\uc744 \ubb3c\uc744 \uc218 \uc788\ub3c4\ub85d \ud55c \ucde8\uc9c0\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a7c,0,"\uc704\ubc18\ud589\uc704\uc5d0 \uc2e4\uc9c8\uc801\uc73c\ub85c \uad00\uc5ec\ud55c \uad6c\uc131\uc0ac\uc5c5\uc790\uc5d0\uac8c\ub3c4 \ucc45\uc784\uc744 \ubb3c\uc744 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uac83\uc740, \uc0ac\uc5c5\uc790\ub2e8\uccb4\ub77c\ub294 \uc870\uc9c1\uc758 \ud615\uc2dd \ub4a4\uc5d0 \uc228\uc5b4 \uac1c\ubcc4 \uc0ac\uc5c5\uc790\uac00 \uc790\uc2e0\uc758 \ucc45\uc784\uc744 \ud68c\ud53c\ud558\ub294 \uac83\uc744 \ubc29\uc9c0\ud558\uace0, \uc2e4\uc9c8\uc801\uc778 \uc704\ubc18\ud589\uc704\uc790\uc5d0\uac8c \uc0c1\uc751\ud558\ub294 \ucc45\uc784\uc744 \ubd80\uacfc\ud568\uc73c\ub85c\uc368 \uaddc\uc81c\uc758 \uc2e4\ud6a8\uc131\uc744 \ub192\uc774\uae30 \uc704\ud55c \ucde8\uc9c0\ub85c \uc774\ud574\ub41c\ub2e4.",B.a_z,B.aab,null)
B.a0E=s(["\uc0ac\uc5c5\uc790\uac00 \uc0c1\ud488\uc744 \uac70\ub798\ud558\uba70 \uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \uac70\ub798\uac00\uaca9\uc744 \uc815\ud558\uc5ec \uadf8 \uac00\uaca9\ub300\ub85c \ud310\ub9e4\ud558\ub3c4\ub85d \uac15\uc81c\ud558\ub294 \ud589\uc704\ub294 \uad6c\uc18d\ub825 \uc5ec\ubd80\uc640 \uc0c1\uad00\uc5c6\uc774 \ud56d\uc0c1 \uae08\uc9c0\ub41c\ub2e4","\uc800\uc791\uad8c\ubc95\uc0c1 \uc800\uc791\ubb3c\ub85c\uc11c \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uace0\uc2dc\ud558\ub294 \uc0c1\ud488\uc758 \uacbd\uc6b0 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uac00 \ud5c8\uc6a9\ub420 \uc218 \uc788\ub2e4","\ucd5c\uc800\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\uc5b4\ub3c4 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uae08\uc9c0\ub294 \uc6a9\uc5ed\uc758 \uc81c\uacf5\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc0ac\uc5c5\uc790\uac00 \uac15\uc81c\ub825 \uc5c6\ub294 \ud76c\ub9dd\uac00\uaca9\uc744 \uc81c\uc2dc\ud558\ub294 \ud589\uc704\ub3c4 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub85c \uae08\uc9c0\ub41c\ub2e4"],t.s)
B.a5P=s(["\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uace0\uc2dc\ud558\ub294 \uc804\uc790\ucd9c\ud310\ubb3c \ub4f1\uc5d0 \ub300\ud574\uc11c\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uac00 \ud5c8\uc6a9\ub41c\ub2e4"],t.s)
B.Qy=s(["\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uc608\uc678"],t.s)
B.ave=new A.b("gen_rp_1","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704",null,"\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.a0E,1,'\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc0ac\uc5c5\uc790\uac00 \uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \uac70\ub798\uac00\uaca9\uc744 \uc815\ud574 \uadf8 \uac00\uaca9\ub300\ub85c \ud310\ub9e4\ud558\ub3c4\ub85d \uac15\uc81c\ud558\uac70\ub098 \uad6c\uc18d\uc870\uac74\uc744 \ubd99\uc774\ub294 \ud589\uc704\ub85c \uc6d0\uce59\uc801\uc73c\ub85c \uae08\uc9c0\ub41c\ub2e4(\uacf5\uc815\uac70\ub798\ubc95 \uc81c46\uc870). \ub2e4\ub9cc \uc608\uc678\uc801\uc73c\ub85c \u300c\uc800\uc791\uad8c\ubc95\u300d\uc0c1 \uc800\uc791\ubb3c \uc911 \uad00\uacc4 \uc911\uc559\ud589\uc815\uae30\uad00\uc758 \uc7a5\uacfc \ud611\uc758\ub97c \uac70\uccd0 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uace0\uc2dc\ud558\ub294 \uc804\uc790\ucd9c\ud310\ubb3c \ub4f1\uc5d0 \ub300\ud574\uc11c\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uac00 \ud5c8\uc6a9\ub41c\ub2e4. \ubc18\uba74 \ucd5c\uc800\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub3c4 "\uc815\ub2f9\ud55c \uc774\uc720"\uac00 \uc788\uc73c\uba74 \ud5c8\uc6a9\ub420 \uc218 \uc788\uace0(\uc120\ud0dd\uc9c0 \u2462\uc740 \uc624\ub2f5), \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc0c1\ud488\ubfd0 \uc544\ub2c8\ub77c \uc6a9\uc5ed\uc758 \uc81c\uacf5\uc5d0\ub3c4 \uc801\uc6a9\ub418\uba70(\uc120\ud0dd\uc9c0 \u2463\ub294 \uc624\ub2f5), \uac15\uc81c\ub825 \uc5c6\ub294 \ub2e8\uc21c \ud76c\ub9dd\uac00\uaca9 \uc81c\uc2dc\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4(\uc120\ud0dd\uc9c0 \u2464\ub294 \uc624\ub2f5)\ub294 \uc810\ub3c4 \ud568\uaed8 \uc815\ub9ac\ud574\uc57c \ud55c\ub2e4.',B.a5P,B.Qy,null)
B.UF=s([u.DM,"\uc0ac\uc5c5\uc790\uac00 \uc18c\ube44\uc790\uc5d0\uac8c \ub2e8\uc21c\ud788 \uad8c\uc7a5\uc18c\ube44\uc790\uac00\uaca9\uc744 \uc54c\ub824\uc8fc\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc790\uc2e0\uc758 \uc0c1\ud488 \uac00\uaca9\uc744 \uc2a4\uc2a4\ub85c \uc778\uc0c1\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uacbd\uc7c1\uc0ac\uc5c5\uc790\uc640 \uac00\uaca9\uc815\ubcf4\ub97c \uad50\ud658\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc815\ubd80\uc5d0 \uac00\uaca9 \uc778\uac00\ub97c \uc2e0\uccad\ud558\ub294 \ud589\uc704"],t.s)
B.WE=s([u.DM],t.s)
