B.asG=new A.b("gen_rpm_def_2","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\uc758\xb7\uc131\ub9bd\uc694\uac74","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \ud575\uc2ec \uc694\uc18c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a6c,0,"\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc0ac\uc5c5\uc790\uac00 \uc815\ud55c \uac00\uaca9\uc744 \uac70\ub798\uc0c1\ub300\ubc29\uc774 \uadf8\ub300\ub85c \ub530\ub974\ub3c4\ub85d \ud558\ub294 \uac15\uc81c\uc131 \ub610\ub294 \uad6c\uc18d\ub825\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \ub2e8\uc21c\ud55c \uad8c\uc720\ub098 \ud76c\ub9dd \ud45c\uc2dc\uc5d0 \uadf8\uce58\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub85c \ubcf4\uae30 \uc5b4\ub835\ub2e4.",B.L4,B.abd,null)
B.a_6=s([u.nG,"\uac00\uaca9\uc758 \uc22b\uc790\uac00 \uc5bc\ub9c8\ub098 \ub192\uc740\uc9c0 \uc5ec\ubd80","\uc0c1\ud488\uc758 \uc885\ub958\uac00 \ubb34\uc5c7\uc778\uc9c0 \uc5ec\ubd80","\uac70\ub798\uc0c1\ub300\ubc29\uc758 \ub9e4\ucd9c \uaddc\ubaa8","\uac70\ub798\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uc9c0\uc5ed"],t.s)
