B.arN=new A.b("gen_rpm_def_5","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\uc758\xb7\uc131\ub9bd\uc694\uac74","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uac00 \ubb38\uc81c\ub418\ub294 \uac70\ub798\ub2e8\uacc4\uc758 \ubc94\uc704\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a8V,0,"\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc0ac\uc5c5\uc790\uac00 \uc9c1\uc811 \uac70\ub798\ud558\ub294 \uc0c1\ub300\ubc29\ubfd0\ub9cc \uc544\ub2c8\ub77c, \uadf8 \ub2e4\uc74c \uac70\ub798\ub2e8\uacc4\uc5d0 \uc788\ub294 \uc0ac\uc5c5\uc790(\uc608: \ub3c4\ub9e4\uc5c5\uc790\uac00 \uc18c\ub9e4\uc5c5\uc790\ub97c \uac70\uccd0 \ud310\ub9e4\ud558\ub294 \uacbd\uc6b0\uc758 \uc18c\ub9e4\uc5c5\uc790)\uae4c\uc9c0\ub3c4 \uaddc\uc81c \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uac70\ub798\ub2e8\uacc4\uac00 \ud655\uc7a5\ub420 \uc218 \uc788\ub2e4.",B.a55,B.aew,null)
B.Nh=s([u.aV,"\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \ud56d\uc0c1 \uc18c\ube44\uc790\uc5d0\uac8c \uc720\ub9ac\ud55c \uacb0\uacfc\ub9cc \uac00\uc838\uc624\uae30 \ub54c\ubb38\uc774\ub2e4","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc81c\uc870\uc5c5\uc790\uc5d0\uac8c\ub9cc \ubd88\ub9ac\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc720\ud1b5\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc720\ub9ac\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uacbd\uc7c1\uacfc \uc804\ud600 \ubb34\uad00\ud55c \uc21c\uc218 \ub0b4\ubd80 \uacbd\uc601 \ubb38\uc81c\uc774\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
