B.arC=new A.b("gen_rpm_type_1","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\ucd5c\uace0\xb7\ucd5c\uc800 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\uc758 \uad6c\ubcc4","\ucd5c\uace0\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc640 \ucd5c\uc800\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 \uaddc\uc81c \uac15\ub3c4 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.YC,0,"\ucd5c\uc800\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704(\uac00\uaca9\uc744 \uc77c\uc815 \uc218\uc900 \uc774\ud558\ub85c \ub0b4\ub9ac\uc9c0 \ubabb\ud558\uac8c \ud558\ub294 \ud589\uc704)\ub294 \uc720\ud1b5\ub2e8\uacc4\uc758 \uac00\uaca9\uacbd\uc7c1\uc744 \uc9c1\uc811\uc801\uc73c\ub85c \uc81c\ud55c\ud558\uc5ec \uc18c\ube44\uc790\uac00\uaca9 \uc0c1\uc2b9\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc6b0\ub824\uac00 \ud06c\uae30 \ub54c\ubb38\uc5d0, \ucd5c\uace0\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc5d0 \ube44\ud574 \uc0c1\ub300\uc801\uc73c\ub85c \ub354 \uc5c4\uaca9\ud558\uac8c \uaddc\uc81c\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.",B.TM,B.LM,null)
B.aaJ=s([u.v2,"\ud56d\uc0c1 \uc18c\ube44\uc790\uac00\uaca9\uc744 \uc778\uc0c1\uc2dc\ud0a4\ub294 \ud6a8\uacfc\ub9cc \uac00\uc838\uc628\ub2e4","\uc720\ud1b5\uc5c5\uc790\uc758 \uc774\uc724\uc744 \ud56d\uc0c1 \uadf9\ub300\ud654\uc2dc\ud0a4\ub294 \ud6a8\uacfc\ub9cc \uac00\uc838\uc628\ub2e4","\uc18c\ube44\uc790 \ud6c4\uc0dd\uacfc\ub294 \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\uc624\uc9c1 \uc81c\uc870\uc5c5\uc790\uc758 \uc774\uc724\ub9cc \uac10\uc18c\uc2dc\ud0a8\ub2e4"],t.s)
