B.apY=new A.b("gen_sp_sanction_1","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc81c\uc7ac","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \ubd80\ub2f9\uc131\uc744 \ud310\ub2e8\ud560 \ub54c \uace0\ub824\ud558\ub294 \uc694\uc18c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.HF,0,"\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \ubd80\ub2f9\uc131\uc744 \ud310\ub2e8\ud560 \ub54c\ub294 \uac70\ub798\uc870\uac74\uc774 \uc815\uc0c1 \uac70\ub798\uc5d0 \ube44\ud574 \uc5bc\ub9c8\ub098 \uc720\ub9ac\ud55c\uc9c0, \uac70\ub798\uaddc\ubaa8\uac00 \uc0c1\ub2f9\ud55c\uc9c0, \uadf8\ub85c \uc778\ud574 \ud2b9\uc218\uad00\uacc4\uc778\uc774 \uc5bb\ub294 \uc774\uc775\uc758 \ud06c\uae30\uac00 \uc5bc\ub9c8\uc778\uc9c0 \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.aej,B.nH,null)
