B.anw=new A.b("gen_sp_sanction_3","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc81c\uc7ac","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uc5d0\uc11c \uc81c\uc7ac\uc758 \uc0c1\ub300\ubc29\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aa4,0,"\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\ub294 \uc774\uc775\uc744 \uc81c\uacf5\ud55c \uc0ac\uc5c5\uc790(\uc9c0\uc6d0 \uc8fc\uccb4)\ubfd0\ub9cc \uc544\ub2c8\ub77c, \uadf8\ub7ec\ud55c \uc774\uc775\uc744 \uc81c\uacf5\ubc1b\uc740 \ud2b9\uc218\uad00\uacc4\uc778(\uc774\uc775\uadc0\uc18d \uc8fc\uccb4)\uc5d0\uac8c\ub3c4 \ud568\uaed8 \uc2dc\uc815\uc870\uce58\ub098 \uacfc\uc9d5\uae08 \ub4f1\uc758 \uc81c\uc7ac\uac00 \ubb38\uc81c\ub420 \uc218 \uc788\ub3c4\ub85d \ud558\uc5ec, \ubd80\ub2f9\ud55c \uc774\uc775 \uc774\uc804\uc758 \uc720\uc778 \uc790\uccb4\ub97c \uc5b5\uc81c\ud558\ub824\ub294 \uad6c\uc870\ub97c \uac16\ub294\ub2e4.",B.a9R,B.afC,null)
B.ZG=s([u.hG,"\ud53c\ud574\ub97c \uc785\uc5b4\ub3c4 \uc5b4\ub5a0\ud55c \uad6c\uc81c\uc218\ub2e8\ub3c4 \uac00\uc9c8 \uc218 \uc5c6\ub2e4","\uc624\uc9c1 \ud615\uc0ac\uace0\uc18c\ub9cc \uac00\ub2a5\ud558\ub2e4","\ud53c\ud574 \uad6c\uc81c\ub294 \uc624\uc9c1 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc7ac\ub7c9\uc5d0 \uc804\uc801\uc73c\ub85c \ub9e1\uaca8\uc9c4\ub2e4","\uad6c\uc81c\uc218\ub2e8\uc740 \ubc95\ub960\uc0c1 \uc804\ud600 \ub9c8\ub828\ub418\uc5b4 \uc788\uc9c0 \uc54a\ub2e4"],t.s)
