B.arZ=new A.b("gen_super_status_6","economic_law","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9","\uac70\ub798\uc0c1\uc9c0\uc704 \uc874\ubd80\uc758 \ud310\ub2e8","\uac70\ub798\uc0c1 \uc9c0\uc704\ub0a8\uc6a9 \uaddc\uc81c\uac00 \ud544\uc694\ud55c \uc815\ucc45\uc801 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a7e,0,"\uac70\ub798\uc0c1 \uc9c0\uc704\ub0a8\uc6a9 \uaddc\uc81c\ub294 \uc0ac\uc5c5\uc790\uac00 \uc2dc\uc7a5\uc9c0\ubc30\uc801 \uc9c0\uc704\uc5d0 \uc774\ub974\uc9c0 \uc54a\ub354\ub77c\ub3c4, \uac1c\ubcc4 \uac70\ub798\uad00\uacc4\uc5d0\uc11c\uc758 \ud798\uc758 \ubd88\uade0\ud615\uc744 \uc774\uc6a9\ud558\uc5ec \uc0c1\ub300\ubc29\uc5d0\uac8c \ubd80\ub2f9\ud55c \uac70\ub798\uc870\uac74\uc744 \uac15\uc694\ud558\ub294 \uac83\uc744 \ubc29\uc9c0\ud568\uc73c\ub85c\uc368 \uac70\ub798\uc758 \uacf5\uc815\uc131\uc744 \ud655\ubcf4\ud558\ub824\ub294 \uc815\ucc45\uc801 \uc774\uc720\uc5d0\uc11c \uc778\uc815\ub41c\ub2e4.",B.a8r,B.Ri,null)
B.Lg=s([u.jZ,"\uac70\ub798\uc0c1\ub300\ubc29\uc774 \uc790\ubc1c\uc801\uc73c\ub85c \uc6d0\ud558\ub294 \uc0c1\ud488\uc744 \uc790\uc720\ub86d\uac8c \uad6c\uc785\ud558\ub3c4\ub85d \ud5c8\uc6a9\ud558\ub294 \ud589\uc704","\uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \ub0ae\uc740 \uac00\uaca9\uc758 \uc0c1\ud488\uc744 \ucd94\ucc9c\ub9cc \ud558\ub294 \ud589\uc704","\uac70\ub798\uc0c1\ub300\ubc29\uc758 \uc0c1\ud488\uc744 \uc790\uc2e0\uc774 \ub300\uc2e0 \uad6c\uc785\ud574\uc8fc\ub294 \ud589\uc704","\uac70\ub798\uc0c1\ub300\ubc29\uacfc \uacf5\ub3d9\uc73c\ub85c \uc0c1\ud488\uc744 \uac1c\ubc1c\ud558\ub294 \ud589\uc704"],t.s)
