B.ar9=new A.b("gen_super_forcebuy_4","economic_law","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9","\uad6c\uc785\uac15\uc81c\xb7\uc774\uc775\uc81c\uacf5\uac15\uc694","\uac00\ub9f9\ubcf8\ubd80\uac00 \uac00\ub9f9\uc810\uc5d0\uac8c \ub9e4\uc7a5 \ub9ac\ub274\uc5bc \ube44\uc6a9\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc744 \uc77c\ubc29\uc801\uc73c\ub85c \ubd80\ub2f4\ud558\ub3c4\ub85d \uac15\uc694\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.QW,0,"\uac00\ub9f9\ubcf8\ubd80\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uac00\ub9f9\uc810\uc5d0\uac8c \ub9e4\uc7a5 \ub9ac\ub274\uc5bc \ube44\uc6a9\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc744 \uc77c\ubc29\uc801\uc73c\ub85c \ubd80\ub2f4\ud558\ub3c4\ub85d \uac15\uc694\ud558\ub294 \ud589\uc704\ub294 \uc774\uc775\uc81c\uacf5\uac15\uc694\uc5d0 \ud574\ub2f9\ud560 \uc18c\uc9c0\uac00 \uc788\uc73c\uba70, \uc774 \uacbd\uc6b0 \ube44\uc6a9 \ubd84\ub2f4\uc758 \ud569\ub9ac\uc131, \uac15\uc694\uc758 \uc815\ub3c4 \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud558\uc5ec \ubd80\ub2f9\uc131\uc774 \ud310\ub2e8\ub41c\ub2e4.",B.a4s,B.U9,null)
B.JH=s([u.mN,"\ub450 \uc720\ud615\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uac1c\ub150\uc73c\ub85c \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uad6c\uc785\uac15\uc81c\ub294 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774\uace0 \uc774\uc775\uc81c\uacf5\uac15\uc694\ub294 \uc544\ub2c8\ub77c\ub294 \ucc28\uc774","\uad6c\uc785\uac15\uc81c\ub294 \uac00\ub9f9\uacc4\uc57d\uc5d0\uc11c\ub9cc, \uc774\uc775\uc81c\uacf5\uac15\uc694\ub294 \uc77c\ubc18 \uac70\ub798\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub41c\ub2e4\ub294 \ucc28\uc774","\uad6c\uc785\uac15\uc81c\ub294 \uc18c\ube44\uc790\ub97c \ub300\uc0c1\uc73c\ub85c, \uc774\uc775\uc81c\uacf5\uac15\uc694\ub294 \uc0ac\uc5c5\uc790\ub97c \ub300\uc0c1\uc73c\ub85c\ub9cc \ubb38\uc81c\ub41c\ub2e4\ub294 \ucc28\uc774"],t.s)
