B.arF=new A.b("gen_sup_remedy_6","economic_law","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704","\uc81c\uc7ac\xb7\uc2dc\uc815\uc870\uce58","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704 \uc81c\ub3c4 \uc804\ubc18\uc5d0 \uad00\ud55c \uc885\ud569\uc801 \uc774\ud574\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Zi,0,"\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704 \uc81c\ub3c4\ub294 \uc5b4\ub5a4 \ud589\uc704\uac00 \uc9c0\uc6d0\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0(\uc758\uc758\xb7\uc720\ud615), \uadf8\uac83\uc774 \ubd80\ub2f9\ud55c\uc9c0(\ud310\ub2e8\uae30\uc900), \ub2e4\ub978 \uc720\uc0ac \uc81c\ub3c4\uc640 \uc5b4\ub5bb\uac8c \uad6c\ubcc4\ub418\ub294\uc9c0, \uc704\ubc18 \uc2dc \uc5b4\ub5a4 \uc81c\uc7ac\uac00 \uac00\ud574\uc9c0\ub294\uc9c0\uac00 \uc720\uae30\uc801\uc73c\ub85c \uc5f0\uacb0\ub41c \uccb4\uacc4\ub85c\uc11c, \uacc4\uc5f4\ud68c\uc0ac \ub4f1\uc5d0 \ub300\ud55c \ubd80\ub2f9\ud55c \uc774\uc775 \ubab0\uc544\uc8fc\uae30\ub97c \ud1b5\ud55c \uacbd\uc7c1\uc65c\uace1\xb7\uacbd\uc81c\ub825\uc9d1\uc911\uc744 \uaddc\uc81c\ud558\ub294 \uac83\uc774 \ud575\uc2ec\uc774\ub2e4.",B.a4c,B.Of,null)
B.a2r=s([u.xo,"\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc740 \uc624\uc9c1 \uc911\uc18c\uae30\uc5c5\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc740 \ud615\uc0ac\ucc98\ubc8c\ub9cc\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc740 \uac1c\ubcc4 \uc18c\ube44\uc790\ub97c \uaddc\uc81c \ub300\uc0c1\uc73c\ub85c \ud55c\ub2e4","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc740 \uc9c0\uc8fc\ud68c\uc0ac \uc124\ub9bd\uc744 \uc804\uba74 \uae08\uc9c0\ud558\ub294 \uac83\uc744 \ub0b4\uc6a9\uc73c\ub85c \ud55c\ub2e4"],t.s)
