B.at0=new A.b("gen_conc_1","economic_law","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c",null,"\uacf5\uc815\uac70\ub798\ubc95\uc0c1 \uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a2r,0,"\uacf5\uc815\uac70\ub798\ubc95\uc0c1 \uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc740 \uc790\uc0b0\ucd1d\uc561 \ub4f1 \uc77c\uc815 \uae30\uc900 \uc774\uc0c1\uc758 \ub300\uae30\uc5c5\uc9d1\ub2e8\uc744 \uacf5\uc2dc\ub300\uc0c1\uae30\uc5c5\uc9d1\ub2e8\xb7\uc0c1\ud638\ucd9c\uc790\uc81c\ud55c\uae30\uc5c5\uc9d1\ub2e8 \ub4f1\uc73c\ub85c \uc9c0\uc815\ud558\uace0, \uc774\ub4e4\uc5d0 \ub300\ud574 \uc0c1\ud638\ucd9c\uc790 \uae08\uc9c0, \uc21c\ud658\ucd9c\uc790 \uc81c\ud55c, \ucc44\ubb34\ubcf4\uc99d \uc81c\ud55c \ub4f1 \uad6c\uc870\uc801 \uaddc\uc81c\ub97c \uc801\uc6a9\ud568\uc73c\ub85c\uc368 \uc18c\uc218\uc758 \ub300\uae30\uc5c5\uc9d1\ub2e8\uc73c\ub85c \uacbd\uc81c\ub825\uc774 \uacfc\ub3c4\ud558\uac8c \uc9d1\uc911\ub418\ub294 \uac83\uc744 \ubc29\uc9c0\ud558\ub294 \uac83\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4. \uc9c0\uc8fc\ud68c\uc0ac \uc124\ub9bd \uc790\uccb4\ub97c \uc804\uba74 \uae08\uc9c0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc77c\uc815 \uc694\uac74 \ud558\uc5d0 \ud5c8\uc6a9\ud558\uba74\uc11c \ud589\uc704 \uaddc\uc81c\ub97c \uac00\ud558\ub294 \ubc29\uc2dd\uc744 \ucde8\ud55c\ub2e4.",B.JU,B.abz,null)
B.J6=s([u.bR,"\uc0ac\uc5c5\uc790\uac00 \uac70\ub798\uc0c1\ub300\ubc29\uacfc \uc0c1\ud488\uc744 \uc11c\ub85c \uad50\ud658\ud558\ub294 \uac83\uc744 \uae08\uc9c0\ud558\ub294 \uaddc\uc81c","\uc0ac\uc5c5\uc790\uac00 \uc740\ud589\uc73c\ub85c\ubd80\ud130 \ub300\ucd9c\uc744 \ubc1b\ub294 \uac83\uc744 \uae08\uc9c0\ud558\ub294 \uaddc\uc81c","\uc0ac\uc5c5\uc790\uac00 \ud574\uc678\uc5d0 \uc790\ud68c\uc0ac\ub97c \uc124\ub9bd\ud558\ub294 \uac83\uc744 \uae08\uc9c0\ud558\ub294 \uaddc\uc81c","\uc0ac\uc5c5\uc790\uac00 \uc8fc\uc2dd\uc744 \uc0c1\uc7a5\ud558\ub294 \uac83\uc744 \uae08\uc9c0\ud558\ub294 \uaddc\uc81c"],t.s)
