B.aqp=new A.b("gen_conc_2","economic_law","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c",null,'\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45 \uc911 "\uc0c1\ud638\ucd9c\uc790 \uae08\uc9c0"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.J6,0,'"\uc0c1\ud638\ucd9c\uc790 \uae08\uc9c0"\ub294 \uc0c1\ud638\ucd9c\uc790\uc81c\ud55c\uae30\uc5c5\uc9d1\ub2e8\uc5d0 \uc18d\ud558\ub294 \uacc4\uc5f4\ud68c\uc0ac\ub4e4\uc774 \uc11c\ub85c \uc0c1\ub300\ubc29 \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc744 \ucde8\ub4dd\ud558\uac70\ub098 \uc18c\uc720\ud558\ub294 \uac83\uc744 \uae08\uc9c0\ud558\ub294 \uaddc\uc81c\ub85c\uc11c, \uac00\uacf5\uc758 \uc790\ubcf8\uc744 \uc774\uc6a9\ud574 \uc9c0\ubc30\ub825\uc744 \ud655\uc7a5\ud558\uace0 \uacc4\uc5f4\ud68c\uc0ac \uac04 \uc704\ud5d8\uc774 \uc11c\ub85c \uc804\uc774\ub418\ub294 \uac83\uc744 \ubc29\uc9c0\ud558\ub824\ub294 \ubaa9\uc801\uc744 \uac16\ub294\ub2e4.',B.Pn,B.a3z,null)
B.NQ=s([u.fs,"\uc21c\ud658\ucd9c\uc790\ub294 \uc18c\ube44\uc790 \ubcf4\ud638\uc640 \uc804\ud600 \ubb34\uad00\ud55c \uac1c\ub150\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\uc21c\ud658\ucd9c\uc790 \uc81c\ud55c\uc740 \uc624\uc9c1 \uc911\uc18c\uae30\uc5c5\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\uae30 \ub54c\ubb38\uc774\ub2e4","\uc21c\ud658\ucd9c\uc790\ub294 \ud56d\uc0c1 \ud68c\uc0ac\uc5d0 \uc774\uc775\ub9cc \uac00\uc838\uc624\uae30 \ub54c\ubb38\uc774\ub2e4","\uc21c\ud658\ucd9c\uc790 \uc81c\ud55c\uc740 \ud615\uc0ac\ucc98\ubc8c\ub9cc\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
