B.ajM=new A.b("gen_conc_3","economic_law","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c",null,'\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45 \uc911 "\uc21c\ud658\ucd9c\uc790 \uc81c\ud55c"\uc774 \ud544\uc694\ud55c \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.NQ,0,"\uc21c\ud658\ucd9c\uc790\ub294 \uacc4\uc5f4\ud68c\uc0ac\ub4e4\uc774 A\ud68c\uc0ac\uac00 B\ud68c\uc0ac\uc5d0, B\ud68c\uc0ac\uac00 C\ud68c\uc0ac\uc5d0, C\ud68c\uc0ac\uac00 \ub2e4\uc2dc A\ud68c\uc0ac\uc5d0 \ucd9c\uc790\ud558\ub294 \uac83\uacfc \uac19\uc774 \uace0\ub9ac(\uc21c\ud658) \ud615\ud0dc\ub85c \uc11c\ub85c \ucd9c\uc790\ud558\ub294 \uad6c\uc870\ub97c \uc758\ubbf8\ud558\uba70, \uc774\ub97c \ud1b5\ud574 \ucd1d\uc218 \ub4f1\uc774 \uc2e4\uc81c \ud22c\uc785\ud55c \uc790\ubcf8\uc5d0 \ube44\ud574 \ud6e8\uc52c \ud070 \uc9c0\ubc30\ub825\uc744 \ud615\uc131\ud560 \uc218 \uc788\uc5b4 \uacbd\uc81c\ub825\uc9d1\uc911\uc744 \uc2ec\ud654\uc2dc\ud0ac \uc6b0\ub824\uac00 \uc788\uc73c\ubbc0\ub85c \uc774\ub97c \uc81c\ud55c\ud560 \ud544\uc694\uac00 \uc788\ub2e4.",B.Nz,B.a32,null)
B.WM=s([u.DZ,"\uc0ac\uc5c5\uc790\uac00 \uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \ub2f4\ubcf4\ub97c \uc694\uad6c\ud558\ub294 \uac83\uc744 \uae08\uc9c0\ud558\ub294 \uaddc\uc81c","\uc0ac\uc5c5\uc790\uac00 \ub300\ucd9c\uae08\ub9ac\ub97c \uc790\uc728\uc801\uc73c\ub85c \uc815\ud558\ub294 \uac83\uc744 \uae08\uc9c0\ud558\ub294 \uaddc\uc81c","\uac1c\uc778\uc774 \ud0c0\uc778\uc758 \ucc44\ubb34\ub97c \ubcf4\uc99d\ud558\ub294 \uac83\uc744 \uc804\uba74 \uae08\uc9c0\ud558\ub294 \uaddc\uc81c","\uae08\uc735\uae30\uad00\uc774 \ub300\ucd9c\uc744 \uac70\ubd80\ud558\ub294 \uac83\uc744 \uae08\uc9c0\ud558\ub294 \uaddc\uc81c"],t.s)
