B.arW=new A.b("gen_conc_4","economic_law","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c",null,'\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45 \uc911 "\ucc44\ubb34\ubcf4\uc99d \uc81c\ud55c"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.WM,0,'"\ucc44\ubb34\ubcf4\uc99d \uc81c\ud55c"\uc740 \uc0c1\ud638\ucd9c\uc790\uc81c\ud55c\uae30\uc5c5\uc9d1\ub2e8\uc5d0 \uc18d\ud558\ub294 \uacc4\uc5f4\ud68c\uc0ac\uac00 \ub2e4\ub978 \uacc4\uc5f4\ud68c\uc0ac\uc758 \uad6d\ub0b4 \uae08\uc735\uae30\uad00\uc5d0 \ub300\ud55c \ucc44\ubb34\ub97c \ubcf4\uc99d\ud558\ub294 \uac83\uc744 \uc6d0\uce59\uc801\uc73c\ub85c \uc81c\ud55c\ud558\ub294 \uaddc\uc81c\ub85c\uc11c, \ud2b9\uc815 \uacc4\uc5f4\ud68c\uc0ac\uc758 \ubd80\uc2e4\uc774 \ubcf4\uc99d\uc744 \ud1b5\ud574 \ub2e4\ub978 \uacc4\uc5f4\ud68c\uc0ac\ub85c \uc804\uc774\ub418\uc5b4 \uae30\uc5c5\uc9d1\ub2e8 \uc804\uccb4\uc640 \uae08\uc735\uc2dc\uc2a4\ud15c\uc758 \uc704\ud5d8\uc73c\ub85c \ud655\uc0b0\ub418\ub294 \uac83\uc744 \ubc29\uc9c0\ud558\ub824\ub294 \ubaa9\uc801\uc744 \uac16\ub294\ub2e4.',B.RP,B.Lk,null)
B.a4z=s([u.j1,"\uc9c0\uc8fc\ud68c\uc0ac\ub294 \uc5b4\ub5a0\ud55c \uaddc\uc81c\ub3c4 \ubc1b\uc9c0 \uc54a\ub294 \uc608\uc678 \uc601\uc5ed\uc774\ub2e4","\uc9c0\uc8fc\ud68c\uc0ac \uc124\ub9bd\uc740 \uc804\uba74\uc801\uc73c\ub85c \uae08\uc9c0\ub41c\ub2e4","\uc9c0\uc8fc\ud68c\uc0ac \uaddc\uc81c\ub294 \uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c\uc640 \uc804\ud600 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ub2e4","\uc9c0\uc8fc\ud68c\uc0ac\ub294 \uc624\uc9c1 \uc911\uc18c\uae30\uc5c5\ub9cc \uc124\ub9bd\ud560 \uc218 \uc788\ub2e4"],t.s)
