B.apS=new A.b("gen_kh_prehist_21","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uc5ec\ub7ec \ub098\ub77c\uc758 \uc131\uc7a5",'(\uac00) \ub098\ub77c\uc758 \ud48d\uc2b5\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"(\uac00)\uc5d0\uc11c\ub294 \uc5ec\uc790\uc544\uc774\ub97c \uc5b4\ub9b4 \ub54c \ub0a8\uc790 \uc9d1\uc5d0\uc11c \ub370\ub824\ub2e4 \ud0a4\uc6b4 \ub4a4, \uc131\uc778\uc774 \ub418\uba74 \ub2e4\uc2dc \uce5c\uc815\uc5d0 \ub3cc\ub824\ubcf4\ub0c8\ub2e4\uac00 \uc608\ubb3c\uc744 \uce58\ub974\uace0 \uc815\uc2dd\uc73c\ub85c \ud63c\uc778\ud558\ub294 \ud48d\uc2b5\uc774 \uc788\uc5c8\ub2e4."',B.Rq,0,"\uc5b4\ub9b0 \uc5ec\uc790\uc544\uc774\ub97c \ubbf8\ub9ac \ub0a8\uc790 \uc9d1\uc5d0\uc11c \ub370\ub824\ub2e4 \ud0a4\uc6b0\ub2e4\uac00 \uc131\uc778\uc774 \ub41c \ud6c4 \uc608\ubb3c\uc744 \uce58\ub974\uace0 \uc815\uc2dd \ud63c\uc778\ud558\ub294 \ud48d\uc2b5\uc740 \uc625\uc800\uc758 \ubbfc\uba70\ub290\ub9ac\uc81c\uc774\ub2e4. \uc625\uc800\ub294 \uc774 \ubc16\uc5d0\ub3c4 \uac00\uc871\uc758 \ubf08\ub97c \ud55c \uacf3\uc5d0 \ubaa8\uc544 \ub450\ub294 \uac00\uc871 \uacf5\ub3d9 \ubb34\ub364(\uace8\uc7a5\uc81c)\uc758 \ud48d\uc2b5\ub3c4 \uc788\uc5c8\ub2e4.",B.a7I,B.a8K,null)
B.XB=s(["\ub2e8\uad81, \uacfc\ud558\ub9c8, \ubc18\uc5b4\ud53c \ub4f1 \ud2b9\uc0b0\ubb3c\ub85c \uc720\uba85\ud558\uc600\ub2e4","\uc0ac\ucd9c\ub3c4\ub97c \ub450\uc5b4 \uc5ec\ub7ec \uac00(\u52a0)\ub4e4\uc774 \uc9c0\uc5ed\uc744 \ub098\ub204\uc5b4 \ub2e4\uc2a4\ub838\ub2e4","\uc81c\uac00 \ud68c\uc758\uc5d0\uc11c \uad6d\uac00\uc758 \uc911\ub300\uc0ac\ub97c \uacb0\uc815\ud558\uc600\ub2e4","\uc18c\ub3c4\ub77c\ub294 \uc2e0\uc131 \uc9c0\uc5ed\uc5d0\uc11c \ucc9c\uad70\uc774 \uc81c\uc0ac\ub97c \uc8fc\uad00\ud558\uc600\ub2e4","\uc655 \uc544\ub798 \uc0c1\uac00\xb7\ub300\ub85c\xb7\ud328\uc790 \ub4f1\uc758 \uad00\uc9c1\uc744 \ub450\uc5c8\ub2e4"],t.s)
B.abt=s(["\ub2e8\uad81, \uacfc\ud558\ub9c8, \ubc18\uc5b4\ud53c \ub4f1 \ud2b9\uc0b0\ubb3c\ub85c \uc720\uba85\ud558\uc600\ub2e4"],t.s)
B.Yf=s(["\ub3d9\uc608\uc758 \ud48d\uc2b5\uacfc \ud2b9\uc0b0\ubb3c"],t.s)
B.akJ=new A.b("gen_kh_prehist_22","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uc5ec\ub7ec \ub098\ub77c\uc758 \uc131\uc7a5",'(\uac00) \ub098\ub77c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"(\uac00)\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc74d\ub77d\uc758 \uc601\uc5ed\uc744 \ud568\ubd80\ub85c \uce68\ubc94\ud558\uba74 \ub178\ube44\uc640 \uc18c\xb7\ub9d0\ub85c \ubc30\uc0c1\ud558\uac8c \ud558\ub294 \ucc45\ud654\ub77c\ub294 \ud48d\uc2b5\uc774 \uc788\uc5c8\ub2e4."',B.XB,0,"\ucc45\ud654\ub294 \ub3d9\uc608\uc758 \ub300\ud45c\uc801 \ud48d\uc2b5\uc73c\ub85c, \uc74d\ub77d \uac04 \uacbd\uacc4\ub97c \uc911\uc2dc\ud558\uc5ec \uc774\ub97c \uce68\ubc94\ud558\uba74 \ub178\ube44\ub098 \uc18c\xb7\ub9d0\ub85c \ubc30\uc0c1\ud558\uac8c \ud558\uc600\ub2e4. \ub3d9\uc608\ub294 \ub2e8\uad81\xb7\uacfc\ud558\ub9c8\xb7\ubc18\uc5b4\ud53c \ub4f1 \ud2b9\uc0b0\ubb3c\ub85c\ub3c4 \uc720\uba85\ud558\uc600\ub2e4. \uc0ac\ucd9c\ub3c4\ub294 \ubd80\uc5ec, \uc81c\uac00 \ud68c\uc758\xb7\uc0c1\uac00\xb7\ub300\ub85c\xb7\ud328\uc790\ub294 \uace0\uad6c\ub824, \uc18c\ub3c4\xb7\ucc9c\uad70\uc740 \uc0bc\ud55c\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.abt,B.Yf,null)
B.Xw=s(["\ucc9c\uad70\uc774 \uc18c\ub3c4\ub77c\ub294 \uc2e0\uc131 \uc9c0\uc5ed\uc5d0\uc11c \ub18d\uacbd\uacfc \uc885\uad50\uc5d0 \ub300\ud55c \uc758\ub840\ub97c \uc8fc\uad00\ud558\uc600\ub2e4","\uc0ac\ucd9c\ub3c4\ub97c \ub450\uc5b4 \uc5ec\ub7ec \uac00\ub4e4\uc774 \ubcc4\ub3c4\uc758 \uc9c0\uc5ed\uc744 \ub2e4\uc2a4\ub838\ub2e4","\uc11c\uc625\uc81c\ub77c\ub294 \ub370\ub9b4\uc0ac\uc704\uc81c \ud48d\uc2b5\uc744 \ud1b5\ud574 \ud63c\uc778 \uad00\uacc4\ub97c \ub9fa\uc5c8\ub2e4","\ubbfc\uba70\ub290\ub9ac\uc81c\ub77c\ub294 \ud63c\uc778 \ud48d\uc2b5\uc73c\ub85c \ub178\ub3d9\ub825\uc744 \ubbf8\ub9ac \ud655\ubcf4\ud558\uc600\ub2e4","\ucc45\ud654\ub97c \ud1b5\ud574 \uc74d\ub77d \uac04\uc758 \uacbd\uacc4\ub97c \uc5c4\uaca9\ud788 \uc9c0\ucf30\ub2e4"],t.s)
B.X7=s(["\ucc9c\uad70\uc774 \uc18c\ub3c4\ub77c\ub294 \uc2e0\uc131 \uc9c0\uc5ed\uc5d0\uc11c \ub18d\uacbd\uacfc \uc885\uad50\uc5d0 \ub300\ud55c \uc758\ub840\ub97c \uc8fc\uad00\ud558\uc600\ub2e4"],t.s)
B.Lx=s(["\uc0bc\ud55c\uc758 \uc81c\uc815 \ubd84\ub9ac\uc640 \uc18c\ub3c4"],t.s)
B.asT=new A.b("gen_kh_prehist_23","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uc5ec\ub7ec \ub098\ub77c\uc758 \uc131\uc7a5",'(\uac00) \ub098\ub77c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"(\uac00)\uc5d0\ub294 \uc2e0\uc9c0, \uc74d\ucc28 \ub4f1\uc73c\ub85c \ubd88\ub9b0 \uc815\uce58\uc801 \uc9c0\ubc30\uc790\uc640, \uc81c\uc0ac\ub97c \uc8fc\uad00\ud558\ub294 \ucc9c\uad70\uc774 \ub530\ub85c \uc874\uc7ac\ud558\ub294 \uc81c\uc815 \ubd84\ub9ac \uc0ac\ud68c\uc600\ub2e4."',B.Xw,0,"\uc2e0\uc9c0\xb7\uc74d\ucc28 \ub4f1 \uc815\uce58\uc801 \uc9c0\ubc30\uc790\uc640 \ucc9c\uad70\uc774\ub77c\ub294 \uc81c\uc0ac\uc7a5\uc774 \ub530\ub85c \uc874\uc7ac\ud55c \uc81c\uc815 \ubd84\ub9ac \uc0ac\ud68c\ub294 \uc0bc\ud55c(\ub9c8\ud55c\xb7\uc9c4\ud55c\xb7\ubcc0\ud55c)\uc774\ub2e4. \ucc9c\uad70\uc740 \uc18c\ub3c4\ub77c\ub294 \uc2e0\uc131 \uc9c0\uc5ed\uc5d0\uc11c \ub18d\uacbd\uacfc \uc885\uad50 \uc758\ub840\ub97c \uc8fc\uad00\ud558\uc600\uc73c\uba70, \uc18c\ub3c4\ub294 \uad70\uc7a5\uc758 \uad8c\ub825\uc774 \ubbf8\uce58\uc9c0 \ubabb\ud558\ub294 \uacf3\uc774\uc5c8\ub2e4.",B.X7,B.Lx,null)
B.acv=s(["\ubcc0\ud55c \uc9c0\uc5ed\uc740 \ucca0\uc774 \ud48d\ubd80\ud558\uac8c \uc0dd\uc0b0\ub418\uc5b4 \ub099\ub791\xb7\uc65c \ub4f1\uc5d0 \uc218\ucd9c\ud558\uc600\ub2e4","\uc0ac\ucd9c\ub3c4\ub97c \ub450\uc5b4 \uc5ec\ub7ec \uac00(\u52a0)\uac00 \ub3c5\uc790\uc801\uc73c\ub85c \uc9c0\uc5ed\uc744 \ub2e4\uc2a4\ub838\ub2e4","\uc11c\uc625\uc81c\ub77c\ub294 \ud63c\uc778 \ud48d\uc2b5\uc744 \ud1b5\ud574 \uc2e0\ub791\uc774 \ucc98\uac00\uc0b4\uc774\ub97c \ud558\uc600\ub2e4","\ubbfc\uba70\ub290\ub9ac\uc81c\ub97c \ud1b5\ud574 \uc5b4\ub9b0 \uc5ec\uc790\uc544\uc774\ub97c \ubbf8\ub9ac \ub370\ub824\ub2e4 \ud0a4\uc6e0\ub2e4","\ub2e8\uad81\xb7\uacfc\ud558\ub9c8\xb7\ubc18\uc5b4\ud53c \ub4f1\uc758 \ud2b9\uc0b0\ubb3c\ub85c \uc720\uba85\ud558\uc600\ub2e4"],t.s)
B.Is=s(["\ubcc0\ud55c \uc9c0\uc5ed\uc740 \ucca0\uc774 \ud48d\ubd80\ud558\uac8c \uc0dd\uc0b0\ub418\uc5b4 \ub099\ub791\xb7\uc65c \ub4f1\uc5d0 \uc218\ucd9c\ud558\uc600\ub2e4"],t.s)
